<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {CarFront,Mail,Lock,ArrowRight} from 'lucide-vue-next';import {useVintro} from '../composables/useVintro';const props=defineProps<{mode:'login'|'register'|'reset'}>();const router=useRouter();const {setSignedIn,notify}=useVintro();const loading=ref(false);const form=ref({name:'Tadej Boncelj',email:'tadej@example.com',password:'vintro2026',marketing:false});const submit=()=>{loading.value=true;setTimeout(()=>{loading.value=false;if(props.mode==='reset'){notify('Password reset link sent')}else{setSignedIn(true);notify(props.mode==='login'?'Welcome back':'Account created');router.push('/')}},650)}
</script>
<template><main class="grid min-h-dvh place-items-center bg-[#efeee9] p-5"><div class="w-full max-w-md"><RouterLink to="/" class="mb-10 block text-center text-3xl font-bold tracking-[-.06em]">vintro<span class="text-accent">.</span></RouterLink><section class="card p-6 shadow-soft md:p-8"><span class="grid h-11 w-11 place-items-center rounded-xl bg-ink text-white"><CarFront :size="21"/></span><h1 class="mt-6 text-3xl font-semibold tracking-[-.04em]">{{mode==='login'?'Welcome back':mode==='register'?'Create your account':'Reset password'}}</h1><p class="mt-2 text-sm leading-6 text-muted">{{mode==='reset'?"We'll send a secure reset link to your email.":'Keep every vehicle record in one trusted place.'}}</p><form @submit.prevent="submit" class="mt-7 space-y-4"><label v-if="mode==='register'"><span class="label">Full name</span><input v-model="form.name" class="field" required autocomplete="name"/></label><label><span class="label">Email</span><div class="relative"><Mail :size="17" class="absolute left-4 top-3.5 text-muted"/><input v-model="form.email" type="email" class="field pl-11" required autocomplete="email"/></div></label><label v-if="mode!=='reset'"><span class="label">Password</span><div class="relative"><Lock :size="17" class="absolute left-4 top-3.5 text-muted"/><input v-model="form.password" type="password" class="field pl-11" required autocomplete="current-password"/></div></label><label v-if="mode==='register'" class="flex items-start gap-3 rounded-xl bg-stone-50 p-3 text-sm"><input v-model="form.marketing" type="checkbox" class="mt-1 accent-[#2d5b4f]"/><span>Send me occasional Vintro product updates. <small class="block text-muted">Optional marketing consent.</small></span></label><button class="btn-primary w-full" :disabled="loading"><span v-if="loading" class="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white"/>{{loading?'Please wait…':mode==='login'?'Log in':mode==='register'?'Create account':'Send reset link'}}<ArrowRight v-if="!loading" :size="17"/></button></form><div class="mt-6 flex justify-center gap-2 text-sm"><template v-if="mode==='login'"><span class="text-muted">New to Vintro?</span><RouterLink to="/register" class="font-semibold text-accent">Create account</RouterLink></template><template v-else><span class="text-muted">Already have an account?</span><RouterLink to="/login" class="font-semibold text-accent">Log in</RouterLink></template></div><RouterLink v-if="mode==='login'" to="/reset-password" class="mt-4 block text-center text-sm text-muted">Forgot password?</RouterLink></section></div></main></template>
